import{_ as p,a0 as o,w as r,s as u,ao as e,I as i,x as a,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 中安裝具體指定的軟件包版本 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中安裝具體指定的軟件包版本 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中安裝具體指定的軟件包版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中安裝具體指定的軟件包版本 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu","title":"如何在 Ubuntu 中安裝具體指定的軟件包版本","tag":"202206","desc":""},"relativePath":"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu.md","filePath":"[post].md"}'),d={name:"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu.md"};function h(b,s,g,k,c,m){const t=o("Link");return r(),u("div",null,[s[25]||(s[25]=e('<h1 id="如何在-ubuntu-中安裝具體指定的軟件包版本" tabindex="-1">如何在 Ubuntu 中安裝具體指定的軟件包版本 <a class="header-anchor" href="#如何在-ubuntu-中安裝具體指定的軟件包版本" aria-label="Permalink to “如何在 Ubuntu 中安裝具體指定的軟件包版本”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/26/145335zcrpducpup4p2ugy.jpg" alt=""></p><p>在 Ubuntu 中想安裝一個軟件包的一個特別指定的版本？你可以通過下面的方式來輕鬆地完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install package_name=package_version</span></span></code></pre></div><p>你如何知道某個軟件包有哪些可用的版本？可以使用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --all-versions package_name</span></span></code></pre></div><p>在下面的屏幕截屏中，你可以看到，我有兩個可用的 VLC 版本，我使用命令來安裝較舊的版本：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-specific-versions-apt-ubuntu.png" alt="install specific versions apt ubuntu"></p><p>聽起來像一個簡單的任務，對吧？但是事情並非看起來那麼簡單。這裏有一些不確定是否會出現，但是可能會涉及的東西。</p><p>這篇教程將涵蓋使用 <code>apt</code> 或 <code>apt-get</code> 命令來安裝一個具體指定的程序的版本的所有的重要的方面。</p><h3 id="安裝一個具體指定版本的程序需要知道的事" tabindex="-1">安裝一個具體指定版本的程序需要知道的事 <a class="header-anchor" href="#安裝一個具體指定版本的程序需要知道的事" aria-label="Permalink to “安裝一個具體指定版本的程序需要知道的事”">​</a></h3><p>在基於 Ubuntu 和 Debian 發行版中，你需要知道一些關於 APT 和存儲庫是如何工作的知識。</p><h4 id="同一個軟件包源沒有較舊的版本" tabindex="-1">同一個軟件包源沒有較舊的版本 <a class="header-anchor" href="#同一個軟件包源沒有較舊的版本" aria-label="Permalink to “同一個軟件包源沒有較舊的版本”">​</a></h4><p>Ubuntu 在其存儲庫中不保留較舊版本的軟件包。在特殊的情況下，你可以暫時性地看到多個版本。例如，你運行 APT 更新（但不升級）時，可能會有一個可用的新版本。在 APT 緩存中，你可以看到同一個軟件包的兩個版本。但是，一旦軟件包被升級到了新的版本，較舊版本的軟件包將從 <strong>APT 緩存</strong> 和存儲庫中移除。</p><h4 id="使用多個軟件包源來使用不同的版本" tabindex="-1">使用多個軟件包源來使用不同的版本 <a class="header-anchor" href="#使用多個軟件包源來使用不同的版本" aria-label="Permalink to “使用多個軟件包源來使用不同的版本”">​</a></h4>',15)),i("p",null,[s[1]||(s[1]=a("為獲取同一個的軟件包的多個版本，你必須得添加多個軟件包源。例如，VLC 是版本 3.x 系列。添加 ",-1)),n(t,{href:"https://launchpad.net/~videolan/+archive/ubuntu/master-daily"},{default:l(()=>[...s[0]||(s[0]=[a("VLC 每日構建 PPA",-1)])]),_:1}),s[2]||(s[2]=a(" 將會提供（不穩定的）版本 4.x 系列。",-1))]),s[26]||(s[26]=i("p",null,[a("同樣，"),i("strong",null,"你可以下載不同版本的 DEB 文件，並安裝它"),a("。")],-1)),s[27]||(s[27]=i("h4",{id:"較高版本編號的版本通常有優先權",tabindex:"-1"},[a("較高版本編號的版本通常有優先權 "),i("a",{class:"header-anchor",href:"#較高版本編號的版本通常有優先權","aria-label":"Permalink to “較高版本編號的版本通常有優先權”"},"​")],-1)),s[28]||(s[28]=i("p",null,"如果你有來自多個軟件包源的相同名稱的軟件，默認情況下，Ubuntu 將安裝可用的最高版本編號的版本。",-1)),s[29]||(s[29]=i("p",null,"在前面的示例中，如果我安裝 VLC ，那麼它將會安裝 4.x 系列的版本，而不是 3.x 系列的版本。",-1)),s[30]||(s[30]=i("h4",{id:"較舊版本將升級到可用的較新版本",tabindex:"-1"},[a("較舊版本將升級到可用的較新版本 "),i("a",{class:"header-anchor",href:"#較舊版本將升級到可用的較新版本","aria-label":"Permalink to “較舊版本將升級到可用的較新版本”"},"​")],-1)),i("p",null,[s[4]||(s[4]=a("這是另外一個可能存在的問題。即使你安裝較舊版本的軟件包，它也會升級到較新的版本（如果存在可用的較新版本）。你必須 ",-1)),n(t,{href:"https://itsfoss.com/prevent-package-update-ubuntu/"},{default:l(()=>[...s[3]||(s[3]=[a("保留該軟件包來防止其升級",-1)])]),_:1}),s[5]||(s[5]=a(" 。",-1))]),s[31]||(s[31]=e(`<h4 id="依賴關係也需要安裝" tabindex="-1">依賴關係也需要安裝 <a class="header-anchor" href="#依賴關係也需要安裝" aria-label="Permalink to “依賴關係也需要安裝”">​</a></h4><p>如果軟件包有依賴關係，你也需要安裝必要的依賴關係軟件包。</p><p>現在，你已經知道一些可能存在的問題，讓我們看看如何解決它們。</p><h3 id="安裝一個軟件包的具體指定版本" tabindex="-1">安裝一個軟件包的具體指定版本 <a class="header-anchor" href="#安裝一個軟件包的具體指定版本" aria-label="Permalink to “安裝一個軟件包的具體指定版本”">​</a></h3><p>在這篇教程中，我將以 VLC 為例。在 Ubuntu 的存儲庫中可獲得 VLC 版本。我添加了每日構建 PPA ，它將向我提供 VLC 的 4.0 版本的候選版本。</p><p>如你所見，在現在的系統中，我有兩個可用的 VLC 版本：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-specific-versions-apt-ubuntu.png" alt="install specific versions apt ubuntu"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~$ apt list -a vlc</span></span>
<span class="line"><span>Listing... Done</span></span>
<span class="line"><span>vlc/jammy 4.0.0~rc1~~git20220516+r92284+296~ubuntu22.04.1 amd64</span></span>
<span class="line"><span>vlc/jammy 3.0.16-1build7 amd64</span></span>
<span class="line"><span>vlc/jammy 3.0.16-1build7 i386</span></span></code></pre></div><p>因為較高版本編號版本有優先權，使用 <code>apt install vlc</code> 命令將會導致安裝 VLC 的 4.0 版本。但是，因為這篇教程的緣由，我想安裝較舊的版本 3.0.16 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install vlc=3.0.16-1build7</span></span></code></pre></div>`,10)),i("p",null,[s[8]||(s[8]=a("但是，這裏會有這樣的事。VLC 軟件包有一些依賴關係，並且這些依賴關係也需要具體指定的版本。因此，在 Ubuntu 為其嘗試安裝最新的版本時，你將會遇到經典的 ",-1)),i("ruby",null,[n(t,{href:"https://itsfoss.com/held-broken-packages-error/"},{default:l(()=>[...s[6]||(s[6]=[a("你已保留殘缺軟件包",-1)])]),_:1}),s[7]||(s[7]=i("rt",null,"you have held broken packages",-1))]),s[9]||(s[9]=a(" 錯誤。",-1))]),s[32]||(s[32]=e(`<p><img src="https://itsfoss.com/wp-content/uploads/2022/05/problem-installing-specific-version-apt-ubuntu-800x365.png" alt="problem installing specific version apt ubuntu"></p><p>為修復這個錯誤，你需要為其提供它所投訴的所有依賴關係的軟件包的具體指定版本。因此，該命令會變成這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install vlc=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-bin=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-base=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-qt=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-video-output=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-l10n=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-access-extra=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-notify=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-samba=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-skins2=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-video-splitter=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-visualization=3.0.16-1build7</span></span></code></pre></div><p>説明一下，每行結尾處的 <code>\\</code> 只是用來將多行命令來寫入同一個命令的一種方式。</p><p><strong>它有作用嗎？在很多情況下，它是有作用的。</strong> 但是，我選擇了一個複雜的 VLC 示例，它有很多依賴關係。甚至這些所涉及的依賴關係也依賴於其它的軟件包。所以，它就變得令人難以處理。</p><p>一種替代的方法是在安裝時指定軟件包源。</p><h4 id="替代方式-指定存儲庫" tabindex="-1">替代方式，指定存儲庫 <a class="header-anchor" href="#替代方式-指定存儲庫" aria-label="Permalink to “替代方式，指定存儲庫”">​</a></h4><p>你已經添加多個軟件包源，因此，你應該對這些軟件包的來源有一些瞭解。</p><p>使用下面的命令來搜索存儲庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-cache policy | less</span></span></code></pre></div><p>注意存儲庫名稱後面的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>500 http://security.ubuntu.com/ubuntu jammy-security/multiverse i386 Packages</span></span>
<span class="line"><span>     release v=22.04,o=Ubuntu,a=jammy-security,n=jammy,l=Ubuntu,c=multiverse,b=i386</span></span>
<span class="line"><span>     origin security.ubuntu.com</span></span></code></pre></div><p>你可以具體指定 <code>o</code>、<code>l</code>、<code>a</code> 等參數。</p><p>在我原來的示例中，我想安裝來自 Ubuntu 存儲庫的 VLC（獲取版本 3.16），而不是安裝來 PPA 的版本（它將向我提供版本 4）。</p><p>因此，下面的命令將安裝 VLC 版本 3.16 及其所有的依賴關係：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -t &quot;o=ubuntu&quot; vlc</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-from-repository-source-800x578.png" alt="install from repository source"></p><p>看起來令人滿意？但是，當你必須更新系統時，問題就來了。它接下來會控訴找不到指定的軟件包版本。</p><p><strong>還能做什麼？</strong></p><p>為安裝較舊的軟件包版本，從你的系統中移除較新版本的軟件包源（如果可能的話）。它將有助於逃脱這些依賴關係地獄。</p><p>如果不能這麼做，檢查你是否可以從其它一些軟件包的打包格式來獲取，像 Snap、Flatpak、AppImage 等等。事實上，Snap 和 Flatpak 也允許你從可用的版本中選擇和安裝。因為這些應用程序是沙盒模式的，所以它很容易管理不同版本的依賴關係。</p><h4 id="保留軟件包-防止升級" tabindex="-1">保留軟件包，防止升級 <a class="header-anchor" href="#保留軟件包-防止升級" aria-label="Permalink to “保留軟件包，防止升級”">​</a></h4><p>如果你完成安裝一個指定的程序版本，你可能想避免意外地升級到較新的版本。實現這一點並不太複雜。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark hold package_name</span></span></code></pre></div><p>你可以免除保留軟件包，以便它能稍後升級：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark unhold package_name</span></span></code></pre></div><p>注意，軟件包的依賴關係不會自動地保留。它們需要單獨地指明。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>如你所見，安裝選定軟件包版本有一定之規。只有當軟件包有依賴關係時，那麼事情就會變得複雜，然後，你就會進入依賴關係地獄。</p><p>我希望你在這篇教程中學到一些新的東西。如果你有問題或建議來改善它，請在評論區告訴我。</p><hr>`,31)),i("p",null,[s[11]||(s[11]=a("via: ",-1)),n(t,{href:"https://itsfoss.com/apt-install-specific-version-2/"},{default:l(()=>[...s[10]||(s[10]=[a("https://itsfoss.com/apt-install-specific-version-2/",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("作者：",-1)),n(t,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...s[12]||(s[12]=[a("Abhishek Prakash",-1)])]),_:1}),s[17]||(s[17]=a(" 選題：",-1)),n(t,{href:"https://github.com/lkxed"},{default:l(()=>[...s[13]||(s[13]=[a("lkxed",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),n(t,{href:"https://github.com/robsean"},{default:l(()=>[...s[14]||(s[14]=[a("robsean",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:l(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[a("Linux中國",-1)])]),_:1}),s[24]||(s[24]=a(" 榮譽推出",-1))])])}const y=p(d,[["render",h]]);export{C as __pageData,y as default};
